func catalogMethodTone(method string) badge.Tone {
	switch strings.ToUpper(method) {
	case "GET":
		return badge.TonePrimary
	case "POST":
		return badge.ToneSuccess
	case "DELETE":
		return badge.ToneDanger
	case "PUT", "PATCH":
		return badge.ToneWarning
	default:
		return badge.ToneDefault
	}
}

